import{_ as e,o as t,c as l,a2 as i}from"./chunks/framework.CDU0sSpB.js";const u=JSON.parse('{"title":"1.3 打通最小任务闭环","description":"让任务能真实执行、审批、产出结果并在失败后恢复。","frontmatter":{"title":"1.3 打通最小任务闭环","description":"让任务能真实执行、审批、产出结果并在失败后恢复。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-1/1-3.md","filePath":"delivery/stage-1/1-3.md","lastUpdated":1794017073000}'),r={name:"delivery/stage-1/1-3.md"};function o(n,a,s,d,_,c){return t(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="_1-3-打通最小任务闭环" tabindex="-1">1.3 打通最小任务闭环 <a class="header-anchor" href="#_1-3-打通最小任务闭环" aria-label="Permalink to &quot;1.3 打通最小任务闭环&quot;">​</a></h1><h2 id="当前状态" tabindex="-1">当前状态 <a class="header-anchor" href="#当前状态" aria-label="Permalink to &quot;当前状态&quot;">​</a></h2><ul><li><strong>已完成：</strong> 本地服务与浏览器界面、任务状态持久化、执行进度、审批预览、一次性外部写入、回执、产物保存和失败恢复均已跑通。</li><li><strong>边界：</strong> 外部写入目前落在本机发件箱或受控工具范围，不等于已连接真实邮件、日历或第三方账户。</li></ul><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>在浏览器里打通最小真实任务闭环：用户创建任务后，系统能实际完成工作、请求必要审批、交出产物，并在失败时恢复或转人工。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><ol><li>做一个足够简单的本地服务和浏览器界面，先支持一个任务同时运行。</li><li>创建任务时记录目标、输入、截止时间、可用范围和允许的动作。</li><li>调用现成的执行能力在受控环境中完成真实工作，并持续显示进度。</li><li>任务状态要能跨刷新和重启保留；失败后可以重试、继续或转人工。</li><li>外部操作必须先展示对象、内容和影响，得到确认后只执行一次，并留下可核对的回执。</li><li>产物要能保存、打开和追溯来源；失败要说明原因和下一步。</li><li>限制系统可访问的文件、账户和网络范围，敏感信息不直接暴露给执行过程。</li></ol>',7)])])}const p=e(r,[["render",o]]);export{u as __pageData,p as default};
